class Solution { public int[] sumOfDistancesInTree(int n,int[][] e) { List<Integer>[]g=new List[n];for(int i=0;i<n;i++)g[i]=new ArrayList<>();for(int[]x:e){g[x[0]].add(x[1]);g[x[1]].add(x[0]);}int[]p=new int[n],sz=new int[n],ans=new int[n],ord=new int[n];Arrays.fill(p,-1);Arrays.fill(sz,1);int k=1;ord[0]=0;for(int i=0;i<k;i++){int u=ord[i];for(int v:g[u])if(v!=p[u]){p[v]=u;ord[k++]=v;}}for(int i=n-1;i>0;i--){int u=ord[i],v=p[u];sz[v]+=sz[u];ans[v]+=ans[u]+sz[u];}for(int i=1;i<n;i++){int u=ord[i];ans[u]=ans[p[u]]-sz[u]+n-sz[u];}return ans;} }
